<?php namespace App\Actions; use App\Models\Order; use InvalidArgumentException; class UpdateOrderStatusAction { public function execute(Order $order, ?string $status = null, ?string $paymentStatus = null): Order { $allowedStatuses = ['Pending', 'Preparing', 'Ready', 'Collected', 'Cancelled']; $allowedPayments = ['Unpaid', 'Paid']; if ($status !== null) { if (!in_array($status, $allowedStatuses, true)) { throw new InvalidArgumentException('Invalid order status.'); } $order->status = $status; } if ($paymentStatus !== null) { if (!in_array($paymentStatus, $allowedPayments, true)) { throw new InvalidArgumentException('Invalid payment status.'); } $order->payment_status = $paymentStatus; } $order->save(); return $order; } }